namespace GeetaStudio.Api;

public static class TalkAdminPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>TALK review</title><style>body{font:18px system-ui;max-width:850px;margin:2rem auto;padding:1rem}input,button{font:inherit;padding:.5rem}label{display:block}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><main><h1>TALK review</h1><p>Private, controlled English learning. Human/live/safety qualification remains pending. New policies must bind reviewed persona, audience and locale records. Questions and answers are absent from default diagnostics.</p><label>Workspace <input id="tenant"></label><button id="load">Load capabilities and problem reports</button><label>Reviewed capability file <input id="file" type="file" accept="application/json"></label><button id="save">Save reviewed capability</button><label>Capability identifier <input id="policy"></label><button id="disable">Disable capability</button><p id="status" role="status"></p><pre id="result"></pre><a href="/talk">Open TALK</a></main><script>
const $=id=>document.getElementById(id);async function api(path,body){const r=await fetch('/api/v1/customer-admin/tenants/'+encodeURIComponent($('tenant').value.trim())+'/talk/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:body?JSON.stringify(body):undefined});const text=await r.text();if(!r.ok)throw Error(text||'Request rejected');return text?JSON.parse(text):null}async function work(f){try{$('status').textContent='Working…';$('result').textContent=JSON.stringify(await f(),null,2);$('status').textContent='Done.'}catch(e){$('status').textContent=e.message}}$('load').onclick=()=>work(async()=>({capabilities:await api('policies'),problems:await api('problems')}));$('save').onclick=()=>work(async()=>{const f=$('file').files[0];if(!f||f.size>32768)throw Error('Select a reviewed file of at most32KB');const data=JSON.parse(await f.text());data.operationId||=crypto.randomUUID();return api('policies',data)});$('disable').onclick=()=>work(()=>api('policies/'+encodeURIComponent($('policy').value.trim())+'/enable?enabled=false',{}));
</script></html>
""";
}
